import {
  Group,
  Mesh,
  PlaneGeometry,
  ConeGeometry,
  DirectionalLight,
  PointLight,
  Vector2,
  Vector3,
  Color
} from 'three';
import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial
} from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  smoothstep,
  time,
  uniform,
  vec4,
  positionLocal
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  const timelines = [];

  // 1. STAGE BACKDROP (Designed-for-dark backdrop to avoid FLAT_VOID)
  const backdropGeo = new PlaneGeometry(8, 7);
  const backdropMat = new MeshBasicNodeMaterial();

  // Vertical Gradient implementation using TSL
  const vUv = uv();
  const gradColor = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10 (at 0)
    mix(
      vec3(0.07, 0.07, 0.102),  // #12121a (at 0.6)
      vec3(0.086, 0.086, 0.114), // #16161d (at 1.0)
      smoothstep(0.6, 1.0, vUv.y)
    ),
    smoothstep(0.0, 0.6, vUv.y)
  );
  backdropMat.colorNode = vec4(gradColor, 1.0);

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);

  // 2. BACK LIGHTS (Product light rig)
  // Strong cool directional back-left rim light
  const backRimLight = new DirectionalLight('#9fb0c4', 1.4);
  backRimLight.position.set(-3, 2, -3);
  group.add(backRimLight);

  // Soft local key fill
  const keyLight = new DirectionalLight('#e8ecf2', 0.8);
  keyLight.position.set(3, 4, 3);
  group.add(keyLight);

  // 3. CAUSTIC STREAK PLANE (y = -1.1)
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });

  // Custom TSL Dispersion Caustic Gradient
  const cUv = uv();
  const cColor = mix(
    vec3(1.0, 0.164, 0.22), // #ff2a38 (at 0.2)
    mix(
      vec3(0.91, 0.925, 0.95), // #e8ecf2 (at 0.5)
      vec3(0.62, 0.69, 0.77),  // #9fb0c4 (at 0.8)
      smoothstep(0.5, 0.8, cUv.x)
    ),
    smoothstep(0.2, 0.5, cUv.x)
  );
  const horizontalFade = smoothstep(0.0, 0.2, cUv.x).mul(smoothstep(1.0, 0.8, cUv.x));
  const verticalFade = smoothstep(0.0, 0.5, cUv.y).mul(smoothstep(1.0, 0.5, cUv.y));
  causticMat.colorNode = vec4(cColor, horizontalFade.mul(verticalFade).mul(0.35));

  const causticMesh = new Mesh(causticGeo, causticMat);
  causticMesh.rotation.x = -Math.PI / 2;
  causticMesh.position.set(0, -1.1, 0.1);
  group.add(causticMesh);

  // 4. THE GLASS PRISM (Equilateral triangular prism)
  // Radius 1.2 / sqrt(3) is the distance from center to vertices for equilateral face with 1.2 side length.
  const radius = 1.2 / Math.sqrt(3);
  const prismGeo = new ConeGeometry(radius, 1.8, 3, 1, false, 0); 
  prismGeo.rotateX(Math.PI / 2); // Orient horizontal along Z axis

  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    color: '#e8ecf2',
    // Apply TSL custom chromatic dispersion mockup in the base color
    colorNode: mix(
      vec3(1.0, 0.164, 0.22), // Red shift
      vec3(0.62, 0.69, 0.77),  // Blue shift
      smoothstep(-0.6, 0.6, positionLocal.x)
    )
  });

  const prismContainer = new Group();
  const prismMesh = new Mesh(prismGeo, prismMat);
  prismContainer.add(prismMesh);

  // 5. EMISSIVE CORE (0.35-unit octahedron)
  const coreGeo = new ConeGeometry(0.35, 0.35, 4, 1);
  // Double-cone matches 3D octahedron topology
  coreGeo.rotateX(Math.PI / 2);
  const coreMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 2.2,
    roughness: 0.2
  });

  const coreMesh = new Mesh(coreGeo, coreMat);
  prismContainer.add(coreMesh);

  // Initial transform of the Prism Container
  prismContainer.rotation.z = (12 * Math.PI) / 180;
  prismContainer.rotation.y = (20 * Math.PI) / 180;
  group.add(prismContainer);

  // Core internal subtle levitation / breathing
  const coreTween = gsap.to(coreMesh.position, {
    y: 0.06,
    duration: 3,
    repeat: -1,
    yoyo: true,
    ease: "power1.inOut"
  });
  timelines.push(coreTween);

  // 6. TYPOGRAPHY / TEXT CONTENT
  const textGroup = new Group();
  textGroup.position.set(0, -1.75, 0.2);

  // Headline
  const headline = ctx.fontAtlas.createText('Light, machined.', {
    fontSize: 0.34, // scaled into 3D units for the scene's view from 68px scale ratio
    color: '#e8ecf2',
    align: 'center'
  });
  textGroup.add(headline);

  // Caption (0.5 units below headline)
  const caption = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
    fontSize: 0.09, // 18px scale ratio
    color: '#ff2a38',
    align: 'center',
    letterSpacingPx: 0.08
  });
  caption.position.y = -0.5;
  textGroup.add(caption);

  group.add(textGroup);

  // 7. INTERACTION / HOVER EFFECTS
  const interactionTarget = new Group();
  prismContainer.add(interactionTarget); // Virtual anchor for rotation calculation

  const state = {
    targetRotX: 0,
    targetRotY: 0,
    causticScaleX: 1
  };

  const handlePointerMove = (event) => {
    // Normalised Device Coordinates
    const x = (event.clientX / window.innerWidth) * 2 - 1;
    const y = -(event.clientY / window.innerHeight) * 2 + 1;

    // Max 10 degrees depth rotation
    const maxRot = (10 * Math.PI) / 180;
    state.targetRotY = x * maxRot;
    state.targetRotX = -y * maxRot;
    state.causticScaleX = 1 + Math.abs(x) * 0.08;

    gsap.to(prismMesh.rotation, {
      x: state.targetRotX,
      y: state.targetRotY,
      duration: 0.35,
      ease: 'power1.out'
    });

    gsap.to(causticMesh.scale, {
      x: state.causticScaleX,
      duration: 0.35,
      ease: 'power1.out'
    });
  };

  const handlePointerLeave = () => {
    // Weighted settle back to origin: 1.04 overshoot to 1.0
    const tl = gsap.timeline();
    tl.to(prismMesh.rotation, {
      x: -0.04 * state.targetRotX,
      y: -0.04 * state.targetRotY,
      duration: 0.45,
      ease: 'power2.out'
    })
    .to(prismMesh.rotation, {
      x: 0,
      y: 0,
      duration: 0.45,
      ease: 'power4.out'
    });

    gsap.to(causticMesh.scale, {
      x: 1,
      duration: 0.9,
      ease: 'power4.out'
    });

    timelines.push(tl);
  };

  // Mount listeners directly to Prism window proxy elements or user interface layer
  group.userData.handlers = {
    pointermove: handlePointerMove,
    pointerleave: handlePointerLeave
  };

  // Apply explicit cinematic primitives
  const primitiveResult = ctx.primitives['depth-rotate'](prismContainer, { maxDeg: 10 });

  // 8. CLEANUP CONTRACT Implementation
  group.userData.cleanup = function() {
    timelines.forEach((tl) => tl.kill());
    if (primitiveResult && primitiveResult.cleanup) {
      primitiveResult.cleanup();
    }
    prismGeo.dispose();
    prismMat.dispose();
    coreGeo.dispose();
    coreMat.dispose();
    causticGeo.dispose();
    causticMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
  };

  return group;
}
